# 0180
save("0180","مراسم وشروط أداء القسم للخريجين",[
("rule",[1],"البند 1 و2","يُجرى حفل تخريج الطلبة في نهاية الفصل الدراسي الأول والفصل الدراسي الثاني لكليات الصيدلة والتمريض والطب البيطري، ويُجرى حفل تخريج سنوي في نهاية الفصل الدراسي الثاني لكليتي الطب البشري وطب الأسنان.",
 "متى يُجرى حفل أداء القسم لخريجي كليات الصيدلة والتمريض والطب البيطري؟","في أي وقت يُقام حفل التخريج لكلية الطب البشري وطب الأسنان؟","كل قديش بسووا حفل قسم لخريجين الصيدلة والتمريض والطب؟"),
("rule",[1],"البند 3 و4","تُجرى مراسم أداء القسم ضمن حفل التخريج الخاص بكل كلية برعاية رئيس الجامعة أو من ينوب عنه وبحضور ممثلين عن الجهات صاحبة العلاقة من النقابات المهنية أو وزارة الصحة، ويُكرَّم الطلبة أثناء الحفل بهدايا رمزية تحمل شعار الجامعة.",
 "من يرعى مراسم أداء القسم للخريجين ومن يحضرها؟","هل يُكرَّم الخريجون في حفل أداء القسم؟","مين بحضر حفل القسم وشو بنعطوا للخريجين؟"),
("rule",[1],"البند 5 و6","يتم التنسيق المسبق لحفل التخريج مع عمادة شؤون الطلبة والأمن الجامعي والقبول والتسجيل والعلاقات العامة ودائرة التغذية، وتعمل كل كلية على إيجاد الدعم اللازم لتغطية نفقات حفل التخريج وأداء القسم من خارج الجامعة، وفي حال تعذر ذلك تلتزم الجامعة بتغطية النفقات على أن تكون بسيطة ورمزية.",
 "من يغطي نفقات حفل التخريج وأداء القسم؟","مع أي جهات يتم التنسيق المسبق لحفل التخريج؟","مين بدفع تكاليف حفل التخريج؟"),
],"a",verified="image")
# 0185
D="تعليمات الأندية الطلابية في الجامعة"
save("0185",D,[
("number",[3],"المادة 3","تُشكَّل الأندية الطلابية بموافقة رئيس الجامعة بناءً على طلب من عميد شؤون الطلبة، شريطة ألا يقل عدد الطلبة الراغبين بتأسيس النادي عن (35) طالباً.",
 "ما الحد الأدنى لعدد الطلبة اللازم لتأسيس نادٍ طلابي؟","من يوافق على تشكيل النادي الطلابي؟","كم طالب لازم عشان نأسس نادي طلابي؟"),
("rule",[2],"المادة 1","تؤسس الأندية الطلابية بإشراف عمادة شؤون الطلبة وفق القرارات التي يصدرها رئيس الجامعة، ويكون مركزها الحرم الجامعي.",
 "من يشرف على الأندية الطلابية في الجامعة؟","أين يكون مركز الأندية الطلابية؟","مين بشرف على النوادي الطلابية؟"),
("rule",[4],"المادة 4","تهدف الأندية الطلابية إلى تشجيع الميول التطوعية والعمل الجماعي بين الطلبة، وتنمية المواهب والهوايات وإكساب الطلبة مهارات الحياة، وإفساح الفرص للمشاركة في الأنشطة، وإتاحة المجال أمام الطلبة غير الأردنيين لإظهار ثقافتهم، وتنمية الاهتمام بالنواحي العلمية والثقافية والفكرية والاجتماعية والتطوعية، وبالتراث الحضاري في الأردن والوطن العربي والعالم الإسلامي.",
 "ما أهداف الأندية الطلابية؟","ما الغايات التي تسعى إليها الأندية الطلابية في الجامعة؟","شو الهدف من النوادي الطلابية؟"),
("rule",[4],"المادة 5","لا يجوز للأندية الطلابية الاشتغال بالأمور السياسية أو الطائفية أو الإقليمية.",
 "هل يجوز للأندية الطلابية العمل في الأمور السياسية؟","ما الأمور الممنوع على الأندية الطلابية الاشتغال بها؟","بقدر النادي الطلابي يشتغل بالسياسة؟"),
("rule",[5],"المادة 6","يتكون كل نادٍ من هيئتين: الهيئة العامة والهيئة الإدارية.",
 "مما تتكون الأندية الطلابية من حيث الهيئات؟","ما الهيئات التي يعمل النادي الطلابي من خلالها؟","شو الهيئات اللي بتكون النادي الطلابي؟"),
("number",[5],"المادة 7","تتكون الهيئة العامة للنادي من جميع الأعضاء المنضمين إليه، على ألا يقل عددهم عن خمس وثلاثين عضواً. وتختص بانتخاب الهيئة الإدارية من بين أعضائها، ومناقشة التقرير السنوي المالي والإداري الذي تقدمه الهيئة الإدارية وإقراره، وإقرار خطة العمل السنوية، وسحب الثقة من الهيئة الإدارية على ألا يتم ذلك إلا بأغلبية ثلثي الأعضاء، والمشاركة في نشاطات النادي من خلال اللجان المختصة.",
 "ما الحد الأدنى لعدد أعضاء الهيئة العامة للنادي الطلابي وما اختصاصاتها؟","ما الأغلبية اللازمة لسحب الثقة من الهيئة الإدارية للنادي؟","كم لازم يكون عدد الهيئة العامة بالنادي وشو بتعمل؟"),
("number",[6],"المادة 8","تتكون الهيئة الإدارية لكل نادٍ من سبعة أعضاء تنتخبهم الهيئة العامة بطريقة الاقتراع السري خلال الفصل الأول من كل عام جامعي. ويُشترط لقانونية الانتخابات أن تمارس عملية الاقتراع نسبة (51%) على الأقل من مجموع الأعضاء العاملين، وإذا لم يكتمل النصاب القانوني تؤجل الانتخابات لمدة أسبوع واحد تصبح بعده قانونية مهما بلغ النصاب.",
 "كم عضواً في الهيئة الإدارية للنادي الطلابي وكيف تُنتخب؟","ما النصاب القانوني لانتخابات الهيئة الإدارية للنادي؟","كم عضو بالهيئة الإدارية للنادي وكيف بنتخبوهم؟"),
("number",[6],"المادة 9","يُشترط في الطالب الذي يرشح نفسه لعضوية الهيئة الإدارية لأي نادٍ ألا يقل معدله التراكمي عن (60%)، وأن يبقى على تخرجه من الجامعة فصلان دراسيان على الأقل، وأن يكون قد أمضى في الجامعة فصلين دراسيين على الأقل، وألا يكون قد صدرت بحقه أية عقوبة تأديبية من درجة إنذار أول فما فوق.",
 "ما شروط ترشح الطالب لعضوية الهيئة الإدارية للنادي؟","ما أدنى معدل تراكمي للترشح للهيئة الإدارية لنادٍ طلابي؟","شو شروط الترشح للهيئة الإدارية للنادي؟"),
("rule",[7],"المادة 10","تنتخب الهيئة الإدارية من بين أعضائها في أول اجتماع رئيساً ونائباً للرئيس وأميناً للسر وأميناً للصندوق بطريقة الاقتراع السري. ويعيّن العميد لكل نادٍ مستشاراً من أعضاء الهيئة التدريسية أو من العاملين في الجامعة يتولى الإشراف على أعمال الهيئة الإدارية للنادي وتوجيهها، دون أن يمارس حق التصويت.",
 "كيف تُوزَّع المناصب داخل الهيئة الإدارية للنادي؟","من يعيّن مستشار النادي الطلابي وهل يحق له التصويت؟","مين بعين مستشار النادي وبصوّت؟"),
("rule",[8],"المادة 11 (و)","في حال رفض الهيئة الإدارية طلب انضمام طالب إلى النادي، يحق لمقدم الطلب استئناف القرار إلى العميد خلال مدة أسبوع من تاريخ تبليغ القرار للطالب.",
 "هل يحق للطالب الاعتراض على رفض انضمامه إلى النادي؟ وخلال كم مدة؟","ما مدة استئناف قرار رفض الانضمام إلى النادي الطلابي؟","اذا رفضوا طلب انضمامي للنادي بقدر أعترض؟"),
("rule",[9],"المادة 13","العضو العامل هو الطالب المسجل والمنتظم في الجامعة لنيل درجة علمية ووافقت الهيئة الإدارية على طلبه المتضمن الانضمام للنادي على أن يلتزم بممارسة النشاط الخاص بذلك النادي. أما العضو المشارك فهو الخريج الذي كان عضواً عاملاً في النادي عندما كان طالباً في الجامعة ويرغب في استمرار ممارسة النشاطات في الأندية متمتعاً بجميع حقوق العضو العامل وملتزماً بجميع التزاماته. والعضو المؤازر هو الخريج الذي يرغب في استمرار عضويته بالنادي ملتزماً بدفع قيمة الاشتراك وبمؤازرة النادي بشتى الوسائل دون أن يمارس النشاطات أو يشترك في التصويت.",
 "ما الفرق بين العضو العامل والعضو المشارك والعضو المؤازر في النادي الطلابي؟","من هو العضو المؤازر في الأندية الطلابية؟","شو الفرق بين العضو العامل والمشارك والمؤازر؟"),
("rule",[10],"المادة 14","تزول العضوية في النادي في إحدى حالتين: الاستقالة الخطية، أو فقدان أحد شروط العضوية.",
 "في أي حالات تزول عضوية الطالب في النادي؟","كيف تنتهي عضوية العضو في النادي الطلابي؟","متى بتنتهي عضوية الطالب بالنادي؟"),
("number",[11],"المادة 15","مدة عضوية الهيئة الإدارية وما يتفرع عنها من لجان سنة واحدة، تجرى بعدها انتخابات جديدة.",
 "ما مدة عضوية الهيئة الإدارية للنادي الطلابي؟","كل كم تجرى انتخابات الهيئة الإدارية للنادي؟","كم سنة مدة الهيئة الإدارية للنادي؟"),
("number",[12],"المادة 17","تسقط العضوية من الهيئة الإدارية إذا تخلف العضو عن حضور جلسات الهيئة ثلاث مرات متتالية أو ست مرات متقطعة دون عذر تقبله الهيئة.",
 "متى تسقط عضوية عضو الهيئة الإدارية بسبب الغياب؟","كم مرة يمكن لعضو الهيئة الإدارية أن يتغيب عن الجلسات؟","كم مرة بقدر أغيب عن اجتماعات الهيئة الإدارية؟"),
("number",[12],"المادة 16","تعتبر عضوية الهيئة الإدارية قانونية إذا حضرها ما يزيد على نصف عدد الأعضاء، وتصدر القرارات بأغلبية أصوات الحاضرين، وفي حالة تساوي الأصوات يرجح الجانب الذي صوت له رئيس الهيئة.",
 "ما النصاب القانوني لاجتماع الهيئة الإدارية للنادي وكيف تصدر قراراتها؟","ماذا يحدث عند تساوي الأصوات في الهيئة الإدارية؟","اذا تساوت الأصوات بالهيئة الإدارية مين بحسم؟"),
("number",[13],"المادة 20","تجتمع الهيئة العامة للنادي مرة كل عام، ويجوز دعوتها لاجتماعات غير عادية بقرار من الهيئة الإدارية أو بناءً على طلب ما يزيد على نصف عدد أعضاء الهيئة العامة.",
 "كم مرة تجتمع الهيئة العامة للنادي الطلابي؟","من يستطيع طلب اجتماع غير عادي للهيئة العامة؟","كل قديش بتجتمع الهيئة العامة للنادي؟"),
("rule",[14],"المادة 23 و24 و25","تبدأ السنة المالية للأندية ببدء العام الجامعي وتنتهي بنهايته، وتودع أموال الأندية باسمها في أي بنك في الحرم الجامعي وتسحب بتوقيع كل من أمين الصندوق والرئيس وأمين السر، ويجري صرف أموال النادي بقرار من الهيئة الإدارية في اجتماع قانوني.",
 "كيف تُدار الأموال في النادي الطلابي ومن يوقع على السحب؟","متى تبدأ السنة المالية للأندية الطلابية؟","مين بوقع على سحب فلوس النادي؟"),
("rule",[15],"المادة 26 و27","تتكون إيرادات الأندية من: اشتراكات الأعضاء، ومساهمة العمادة في دعم الأندية الطلابية، وريع النشاطات التي يقوم بها النادي، والتبرعات والهبات التي يوافق عليها العميد، وأية إيرادات أخرى يوافق عليها العميد.",
 "ما مصادر إيرادات الأندية الطلابية؟","من أين تحصل الأندية الطلابية على أموالها؟","شو مصادر دخل النادي الطلابي؟"),
("rule",[16],"المادة 31","لا يحل النادي إلا بقرار من الرئيس بناءً على تنسيب من العميد، وفي هذه الحالة تؤول أموال النادي وموجوداته إلى العمادة.",
 "من يملك قرار حل النادي الطلابي وإلى أين تؤول أمواله؟","ماذا يحدث لأموال النادي الطلابي إذا تم حله؟","اذا انحل النادي وين بروح مصاريفه؟"),
],"a",verified="image")
# 0188
save("0188","تعليمات المفقودات الخاصة بالطلبة والعاملين في الجامعة",[
("procedure",[2],"المادة 2 و3","على كل من يفقد شيئاً من الطلبة أو العاملين داخل الحرم الجامعي أن يعلم دائرة الخدمات الطلابية في عمادة شؤون الطلبة بذلك خلال أسبوع. وعلى كل موظف أو طالب أو عامل يعثر على شيء مفقود داخل الحرم الجامعي أو في وسائل النقل العام التي يستعملها أن يقوم بتسليمه إلى دائرة الخدمات الطلابية في عمادة شؤون الطلبة بأسرع ما يمكن.",
 "ماذا أفعل إذا فقدت شيئاً داخل الحرم الجامعي؟ وخلال كم مدة؟","إلى أين أسلّم شيئاً مفقوداً وجدته في الجامعة؟","اذا ضاع مني اشي بالجامعة لمين برجع وخلال قديش؟"),
("number",[4],"المادة 5","في حالة العثور على مفقودات خاصة داخل الحرم الجامعي تقوم عمادة شؤون الطلبة بالإعلان عنها في كليات الجامعة ومرافقها خلال فترة زمنية تستمر مدة شهر ونصف، على ثلاث مرات متتالية: الأول حال قيام الشخص بالتبليغ عن فقدان شيء خاص به أو عثوره على مفقودات خاصة بغيره، والثاني بعد أسبوعين من تاريخ الإعلان الأول، والثالث في حالة عدم مراجعة أي من الموظفين أو العاملين أو الطلبة بشأن الإعلانات وذلك في نهاية الشهر الأول من تاريخ أو إعلان ويستمر مدة أسبوعين على لوحة الإعلانات الخاصة بكل كلية أو مرفق في الجامعة.",
 "كم مرة وخلال أي مدة تُعلن عمادة شؤون الطلبة عن المفقودات؟","متى يُجرى الإعلان الثاني والثالث عن المفقودات؟","كيف بنعلنوا عن المفقودات بالجامعة؟"),
("rule",[6],"المادة 6 و7","يُشترط في الشخص الذي يدّعي ملكية المفقودات المعلن عنها أن يتعرف عليها ويحدد أوصافها أمام لجنة يشكلها عميد شؤون الطلبة برئاسته أو رئاسة مدير دائرة الخدمات الطلابية وعضوية عضو آخر، وفي حال ثبوت ملكيتها يسلَّم له المفقود بإيصال خاص يعد لهذا الغرض.",
 "كيف أثبت ملكيتي لشيء مفقود وجدته الجامعة؟","من يحدد ملكية المفقودات المعلن عنها؟","كيف بستلم غرضي المفقود من الجامعة؟"),
("number",[7],"المادة 8","في حال عدم تقدم أي من أصحاب المفقودات للتعرف عليها أو تسلمها وفق ما ورد في المواد السابقة وخلال مدة شهر ونصف من وجودها في دائرة الخدمات الطلابية، فإن الدائرة تقوم ببيعها وإيداع ثمنها في صندوق الطلبة الفقراء بناءً على قرار من لجنة الصندوق.",
 "ماذا يحدث للمفقودات التي لم يطالب بها أحد خلال شهر ونصف؟","أين يذهب ثمن المفقودات التي تباع؟","شو بصير بالمفقودات اللي ما حدا بسأل عنها؟"),
],"a",verified="image")
# 0191
save("0191","تعليمات الحوافز التشجيعية للطلبة المتميزين في الأنشطة اللامنهجية",[
("number",[3],"المادة 3","يُمنح الطالب المتميز أو الطلبة المتميزون المشاركون في فرق الجامعة الرياضية أو الفنية أو الثقافية أو الاجتماعية مكافأة مالية في العام الدراسي الذي حقق فيه الإنجاز أو التفوق ولمرة واحدة، تبلغ (300) دينار عند حصوله أو حصول فريقه على المركز الأول في البطولة أو النشاط، و(200) دينار للمركز الثاني، و(100) دينار للمركز الثالث، وترصد في حساب الطالب لدى الدائرة المالية لغايات الرسوم الجامعية وعدم صرفها نقداً.",
 "كم تبلغ المكافأة المالية للطلبة المتميزين في الأنشطة اللامنهجية؟","كم مكافأة الطالب الحاصل على المركز الأول أو الثاني أو الثالث في بطولة؟","كم بحصل الطالب اذا فاز بالمركز الأول ببطولة؟"),
("rule",[3],"المادة 3 (طريقة الصرف)","ترصد مكافأة الطالب المتميز في حسابه لدى الدائرة المالية لغايات الرسوم الجامعية، ولا تُصرف نقداً.",
 "هل تُصرف مكافأة الطالب المتميز نقداً؟","كيف تُمنح الحوافز المالية للطلبة المتميزين في الأنشطة؟","المكافأة بتنعطى كاش ولا بتنحسب من الرسوم؟"),
("number",[4],"المادة 4","يُشترط في الطالب المستفيد من الحوافز: أن يلتزم بتدريبات ومشاركات فرق الجامعة الداخلية والخارجية وتعليمات مشرف النشاط وفق البرامج المعدة لذلك، وألا يقل معدله التراكمي عن (2.1)، وألا يكون قد وقع بحقه أي عقوبة تأديبية مهما كان نوعها وفق نظام تأديب الطلبة في الجامعة، وألا يكون قد تعرض لعقوبة رياضية ومنها الطرد أو الحرمان من المباراة أثناء اللعب، وأن يحظى بترشيح خطي وتقارير إيجابية من مشرفي ومدربي الأنشطة.",
 "ما شروط استفادة الطالب من الحوافز التشجيعية للأنشطة اللامنهجية؟","ما أدنى معدل تراكمي للحصول على حوافز الأنشطة؟","شو شروط الطالب عشان ياخد حوافز الأنشطة؟"),
],"a",verified="image")
# 0192
save("0192","تعليمات اشتراك الطلبة في صناديق بريد الجامعة",[
("rule",[2],"المادة 1 و2","يُعتبر كل طالب مسجل في الجامعة مشتركاً في صندوق البريد داخل الجامعة، ويُعتبر الاشتراك في الصندوق سنوياً لمدة عام دراسي ابتداءً من 10/1 ولغاية 9/30 من كل عام دراسي، ويعتبر الاشتراك منتهياً في حالة الانسحاب من الجامعة أو التخرج.",
 "هل يُعتبر كل طالب مشتركاً في صندوق بريد الجامعة؟ ومتى تبدأ مدة الاشتراك؟","متى ينتهي الاشتراك في صندوق بريد الجامعة؟","كل طالب إله صندوق بريد بالجامعة؟ ومن متى لمتى؟"),
("number",[3],"المادة 3 و4 و5","تُستوفى رسوم الاشتراك فصلياً مع الرسوم الجامعية المقررة، ويُعطى الطالب للمرة الأولى مفتاحاً لصندوق البريد طيلة مدة دراسته، ويدفع مبلغاً مقداره ثلاثة دنانير ونصف دينار إذا تسبب في إتلاف قفل الصندوق أو فقد المفتاح.",
 "كم يدفع الطالب إذا فقد مفتاح صندوق البريد أو أتلف القفل؟","هل يُعطى الطالب مفتاح صندوق البريد مجاناً؟","اذا ضيعت مفتاح صندوق البريد كم بدفع؟"),
("rule",[4],"المادة 6 و7","لا يجوز لأي طالب مشترك في صندوق البريد صنع مفتاح إضافي لصندوقه أو إعارته لطالب آخر، أو التنازل عن اشتراكه لطالب آخر، أو العبث بالرسائل الواردة لزملائه، أو الاحتفاظ بأية رسالة وجدت خطأً في الصندوق (بل يجب إعادتها فوراً إلى مكتب البريد)، أو التخطيط أو الكتابة على صندوق البريد أو العبث به. ومن يخالف ذلك يعرض نفسه للعقوبات المنصوص عليها في نظام تأديب الطلبة.",
 "ما الأفعال الممنوعة على الطالب المشترك في صندوق البريد؟","هل يجوز إعارة مفتاح صندوق بريدي لزميلي؟","بقدر أصنع نسخة ثانية من مفتاح صندوق البريد؟"),
("rule",[5],"المادة 8","دائرة الخدمات الطلابية في عمادة شؤون الطلبة هي الجهة المشرفة على تنظيم استخدام الصناديق البريدية من قبل الطلاب وتحتفظ بالسجلات المطلوبة لذلك.",
 "من الجهة المشرفة على صناديق بريد الطلبة؟","أي دائرة تنظم استخدام صناديق البريد الطلابية؟","مين بنظم صناديق بريد الطلاب؟"),
],"a",verified="image")
# 0189
save("0189","الأسس المعتمدة لاختيار الطلبة المتفوقين في النشاط الرياضي",[
("number",[1],"البند (أ) و(ب)","تُطبق هذه الأسس على الطلبة الأردنيين الحاصلين على شهادة الدراسة الثانوية العامة الأردنية وفي نفس العام، شريطة ألا يقل معدل الطالب عن الحد الأدنى للقبول في الجامعة، ويُقبل عشرون طالباً في التفوق الرياضي.",
 "كم طالباً يُقبل على أساس التفوق الرياضي وما شرط معدلهم؟","هل يشترط حد أدنى للمعدل لقبول المتفوق رياضياً؟","كم طالب بنقبل بالتفوق الرياضي؟"),
("number",[1],"البند (ح)","تختار اللجنة الطلبة الذين تنطبق عليهم شروط التفوق في ضوء المعايير التالية: الاختبار العملي لمهارة اللعبة والأداء العام ويخصص له (75%)، ومعدل الطالب في امتحان الثانوية العامة ويخصص له (25%).",
 "ما نسب معايير اختيار الطلبة المتفوقين رياضياً؟","كم تبلغ نسبة معدل الثانوية العامة في اختيار المتفوق رياضياً؟","كيف بتختاروا المتفوقين رياضياً؟ وكم نسبة المعدل؟"),
("rule",[1],"البند (د)","يقدم الطالب الراغب في الدراسة بالجامعة على أساس التفوق الرياضي إحدى الشهادات التالية: لاعب في المنتخب الوطني أو الأولمبي أو الشباب بموجب شهادة صادرة عن الاتحاد الرياضي المعني ومصدقة من اللجنة الأولمبية الأردنية، أو لاعب في أندية الدرجة الممتازة بالنسبة لكرة القدم أو الأولى بالنسبة للألعاب الأخرى بشهادة من الاتحاد المعني واللجنة الأولمبية، أو لاعب في منتخب وزارة التربية والتعليم أو مديرية التربية والتعليم بشهادة صادرة عن الوزارة أو المديرية، أو الحاصل على الحزام الأسود (واحد دان وما فوق) في ألعاب الدفاع عن النفس كالكراتيه والتايكواندو، أو اللاعب الحاصل فريقه على المركز الأول في بطولة مدرسية رسمية من البطولات التي تنظمها مديريات التربية والتعليم أو مديرية الثقافة العسكرية.",
 "ما الشهادات المطلوبة للقبول على أساس التفوق الرياضي؟","هل الحزام الأسود يؤهل للقبول بالتفوق الرياضي؟","شو الشهادات اللي بحتاجها عشان أتقبل بالتفوق الرياضي؟"),
("rule",[1],"البند (و) و(ط) و(ل)","يشكل رئيس الجامعة سنوياً لجنة إشراف على اختبار قدرات الطلبة تتكون من عميد شؤون الطلبة رئيساً ومدير دائرة النشاط الرياضي وعضو هيئة تدريس مختص بالتربية الرياضية عضوين. ويوقع الطالب وولي أمره تعهداً خطياً بالمشاركة في الأنشطة الرياضية التي تشرف عليها عمادة شؤون الطلبة، وتطبق بحق الطالب الممتنع عن المشاركة الإجراءات التأديبية المناسبة بما فيها الفصل من الجامعة.",
 "ماذا يحدث للطالب المقبول بالتفوق الرياضي إذا امتنع عن المشاركة في الأنشطة؟","من يتكون منهم لجنة الإشراف على اختبار قدرات المتفوقين رياضياً؟","شو بصير إذا المقبول رياضياً ما شارك بالأنشطة؟"),
],"a",verified="image")
# 0190 (text)
save("0190","الأسس المعتمدة لاختيار الطلبة المتفوقين في النشاط الفني",[
("number",[1],"البند (أ) و(ب) و(ج)","تُطبق الأسس على الطلبة الأردنيين الحاصلين على الثانوية العامة الأردنية في نفس العام شريطة ألا يقل المعدل عن الحد الأدنى للقبول، ويُقبل خمسة عشر طالباً متفوقاً فنياً، والمتفوق فنياً هو من يمتلك المهارة الفنية في الموسيقى (الغناء والعزف) أو الفنون التطبيقية (فن تشكيلي، رسم، نحت وما يشملها).",
 "كم طالباً يُقبل على أساس التفوق الفني وفي أي مجالات؟","ما المجالات الفنية المعتمدة للقبول بالتفوق الفني؟","كم طالب بنقبل بالتفوق الفني وبأي مجالات؟"),
("number",[1],"البند (ط)","تختار اللجنة الطلبة الذين تنطبق عليهم شروط التفوق الفني في ضوء معيارين: المستوى الفني ويخصص له (75%)، ومعدل الطالب في امتحان الثانوية العامة ويخصص له (25%).",
 "ما نسب معايير اختيار المتفوقين فنياً؟","كم نسبة المستوى الفني ومعدل الثانوية في القبول على أساس التفوق الفني؟","كيف بختاروا المتفوقين فنياً؟"),
("rule",[1],"البند (ح)","يقدم الطالب الراغب في دخول الجامعة على أساس التفوق الفني في الفنون التطبيقية ثلاثة نماذج من أعماله ويخضع لاختبار عملي أمام اللجنة الفنية المختصة.",
 "ماذا يقدم الطالب الراغب بالقبول على أساس التفوق في الفنون التطبيقية؟","كم نموذجاً من الأعمال يقدمه المتقدم بالتفوق الفني؟","شو بقدم إذا بدي أتقبل بالفنون التطبيقية؟"),
],"a",verified="text")
